:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --bar-bg: #0f3460;
  --bar-fill: #e94560;
  --hover: #ff6b81;
  --focus: #ffd369;
  --pressed: #c2314a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 500px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  text-align: center;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.options {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.option {
  background: var(--secondary);
  border: 2px solid transparent;
  border-radius: 12px;
  padding: 12px 16px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: left;
  color: var(--text);
  font-size: 1rem;
  font-family: inherit;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.option:hover {
  background: #1a4a7a;
  border-color: var(--hover);
}

.option:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.option:active {
  background: var(--pressed);
}

.option.voted {
  border-color: var(--primary);
  background: #1e3a5f;
}

.option-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
}

.option-label {
  flex: 1;
}

.vote-count {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-left: 8px;
  white-space: nowrap;
}

.bar-container {
  width: 100%;
  height: 8px;
  background: var(--bar-bg);
  border-radius: 4px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 0%;
  background: var(--bar-fill);
  border-radius: 4px;
  transition: width 0.3s ease;
}

.percentage {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-align: right;
  min-width: 40px;
}

.actions {
  display: flex;
  justify-content: center;
  margin-bottom: 16px;
}

.reset-btn {
  background: transparent;
  border: 2px solid var(--primary);
  color: var(--primary);
  border-radius: 8px;
  padding: 10px 24px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.reset-btn:hover {
  background: var(--primary);
  color: #fff;
}

.reset-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.reset-btn:active {
  background: var(--pressed);
  border-color: var(--pressed);
  color: #fff;
}

.status {
  text-align: center;
  font-size: 0.9rem;
  color: var(--text-muted);
  min-height: 1.5em;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .option {
    padding: 10px 12px;
  }
}

const question = "What is the best pixel art style?";
const initialOptions = [
  { label: "8-bit", votes: 0 },
  { label: "16-bit", votes: 0 },
  { label: "32-bit", votes: 0 },
  { label: "HD-2D", votes: 0 }
];

let options = initialOptions.map(o => ({ ...o }));
let userVote = null;

const optionsContainer = document.getElementById('options');
const resetBtn = document.getElementById('reset');
const statusEl = document.getElementById('status');

function render() {
  const totalVotes = options.reduce((sum, o) => sum + o.votes, 0);
  optionsContainer.innerHTML = '';

  options.forEach((opt, index) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'option' + (userVote === index ? ' voted' : '');
    btn.setAttribute('aria-pressed', userVote === index ? 'true' : 'false');
    btn.setAttribute('aria-label', `${opt.label}, ${opt.votes} votes, ${totalVotes ? Math.round((opt.votes / totalVotes) * 100) : 0} percent`);

    const header = document.createElement('div');
    header.className = 'option-header';

    const labelSpan = document.createElement('span');
    labelSpan.className = 'option-label';
    labelSpan.textContent = opt.label;

    const countSpan = document.createElement('span');
    countSpan.className = 'vote-count';
    countSpan.textContent = `${opt.votes} vote${opt.votes !== 1 ? 's' : ''}`;

    header.appendChild(labelSpan);
    header.appendChild(countSpan);

    const barContainer = document.createElement('div');
    barContainer.className = 'bar-container';
    const barFill = document.createElement('div');
    barFill.className = 'bar-fill';
    const pct = totalVotes ? (opt.votes / totalVotes) * 100 : 0;
    barFill.style.width = `${pct}%`;
    barContainer.appendChild(barFill);

    const pctSpan = document.createElement('span');
    pctSpan.className = 'percentage';
    pctSpan.textContent = `${Math.round(pct)}%`;

    btn.appendChild(header);
    btn.appendChild(barContainer);
    btn.appendChild(pctSpan);

    btn.addEventListener('click', () => handleVote(index));
    optionsContainer.appendChild(btn);
  });

  statusEl.textContent = userVote !== null ? `You voted for ${options[userVote].label}. Click another option to change.` : 'Click an option to vote.';
}

function handleVote(index) {
  if (userVote === index) return;

  if (userVote !== null) {
    options[userVote].votes = Math.max(0, options[userVote].votes - 1);
  }

  options[index].votes += 1;
  userVote = index;
  render();
}

function resetVotes() {
  options = initialOptions.map(o => ({ ...o }));
  userVote = null;
  render();
  statusEl.textContent = 'Votes reset. Click an option to vote.';
}

resetBtn.addEventListener('click', resetVotes);

render();
